comms.text:
@1 וִיהֵי אֲרֵי תֵעוּל לְאַרְעָא דִי יְיָ אֱלָהָךְ יָהֵב לָךְ אַחֲסָנָא וְתֵירְתַהּ וְתֵיתֵב בַּהּ:
@2 וְתִסַב מֵרֵישׁ כָּל אִבָּא דְאַרְעָא דִי תָעֵל מֵאַרְעָךְ דִי יְיָ אֱלָהָךְ יָהֵב לָךְ וּתְשַׁוֵי בְסַלָא וּתְהַךְ לְאַתְרָא דִי יִתִּרְעֵי יְיָ אֱלָהָךְ לְאַשְׁרָאָה שְׁכִנְתֵּהּ תַּמָן:
@3 וְתֵיתֵי לְוָת כַּהֲנָא דִי יְהֵי בְּיוֹמַיָא הָאִנוּן וְתֵימַר לֵהּ חַוֵיתִי יוֹמָא דֵין קֳדָם יְיָ אֱלָהָךְ אֲרֵי עַלִית לְאַרְעָא דִי קַיִים יְיָ לַאֲבָהָתָנָא לְמִתַּן לָנָא:
@4 וְיִסַב כַּהֲנָא סַלָא מִידָךְ וְיַחְתִנֵהּ קֳדָם מַדְבְּחָא דַיְיָ אֱלָהָךְ:
@5 וְתָתֵיב וְתֵימַר קֳדָם יְיָ אֱלָהָךְ לָבָן אֲרָמָאָה בָּעָא לְאוֹבָדָא יָת אַבָּא וּנְחַת לְמִצְרַיִם וְדָר תַּמָן בְּעַם זְעֵר וַהֲוָה תַמָן לְעַם רַב תַּקִיף וְסַגִי:
@6 וְאַבְאִישׁוּ לָנָא מִצְרָאֵי וְעַנְיָנָא וִיהָבוּ עֲלָנָא פָּלְחָנָא קַשְׁיָא:
@7 וְצַלֵינָא קֳדָם יְיָ אֱלָהָא דַאֲבָהָתָנָא וְקַבִּיל יְיָ צְלוֹתָנָא וּגְלֵי קֳדָמוֹהִי עַמְלָנָא וְלֵאוּתָנָא וְדוּחֲקָנָא:
@8 וְאַפְּקָנָא יְיָ מִמִצְרַיִם בִּידָא תַקִיפָא וּבִדְרָעָא מְרַמְמָא וּבְחֶזְוָנָא רַבָּא וּבְאָתִין וּבְמוֹפְתִין:
@9 וְאַיְתָנָא לְאַתְרָא הָדֵין וִיהַב לָנָא יָת אַרְעָא הָדָא אַרְעָא עָבְדָא חֲלַב וּדְבָש:
@10 וּכְעַן הָא אַיְתֵתִי יָת רֵישׁ אִבָּא דְאַרְעָא דִיהַבְתְּ לִי יְיָ וְתַחְתִנֵהּ קֳדָם יְיָ אֱלָהָךְ וְתִסְגוּד קֳדָם יְיָ אֱלָהָךְ:
@11 וְתֶחֱדֵי בְכָל טַבְתָא דִי יְהַב לָךְ יְיָ אֱלָהָךְ וְלֶאֱנַשׁ בֵּיתָךְ אַתְּ וְלֵוָאֵי וְגִיוֹרָא דִי בֵינָךְ:
@12 אֲרֵי תְשֵׁצֵי לְעַשָׂרָא יָת כָּל מַעְשַׂר עֲלַלְתָּךְ בְּשַׁתָּא תְלִיתָאָה שְׁנַת מַעְשְׂרָא וְתִתֵּן לְלֵוָאֵי לְגִיוֹרָא לְיִתַּמָא וּלְאַרְמְלָא וְיֵכְלוּן בְּקִרְוָיךְ וְיִשְׂבְּעוּן:
@13 וְתֵימַר קֳדָם יְיָ אֱלָהָךְ פַּלֵתִי קֹדֶשׁ מַעְשְׂרָא מִן בֵּיתָא וְאַף יְהָבִתֵּהּ לְלֵוָאֵי וּלְגִיוֹרָא לְיִתַּמָא וּלְאַרְמְלָא כְּכָל פִּקוּדָךְ דִי פַקִדְתַּנִי לָא עֲבָרִית מִפִּקוּדָיךְ וְלָא אִתִּנְשֵׁיתִי:
@14 לָא אֲכָלִית בְּאֶבְלִי מִנֵהּ וְלָא פַלֵתִי מִנֵהּ בִּמְסָאָב וְלָא יְהָבִית מִנֵהּ לְמִית קַבֵּלִית לְמֵימְרָא דַיְיָ אֱלָהָי עֲבָדִית כְּכֹלּ דִי פַקִדְתַּנִי:
@15 אִסְתְּכִי מִמְדוֹר קוּדְשָׁךְ מִן שְׁמַיָא וּבָרֵךְ יָת עַמָךְ יָת יִשְׂרָאֵל וְיָת אַרְעָא דִי יְהַבְתְּ לָנָא כְּמָא דִי קַיֶמְתָּא לַאֲבָהָתָנָא אֲרַע עָבְדָא חֲלַב וּדְבָשׁ:
@16 יוֹמָא הָדֵין יְיָ אֱלָהָךְ מְפַקְדָךְ לְמֶעְבַּד יָת קְיָמַיָא הָאִלֵין וְיָת דִינַיָא וְתִטַר וְתַעְבֵּד יָתְהוֹן בְּכָל לִבָּךְ וּבְכָל נַפְשָׁךְ:
@17 יָת יְיָ חֲטַּבְתָּ יוֹמָא דֵין לְמֶהֱוֵי לָךְ לֶאֱלָהּ וְלִמְהַךְ בְּאָרְחָן דְתָקְנָן קֳדָמוֹהִי וּלְמִטַר קְיָמוֹהִי וּפִקוּדוֹהִי וְדִינוֹהִי וּלְקַבָּלָא לְמֵימְרֵהּ:
@18 וַיְיָ חָטְבָךְ יוֹמָא דֵין לְמֶהֱוֵי לֵהּ לְעַם חַבִּיב כְּמָא דִי מַלִיל לָךְ וּלְמִטַר כָּל פִּקוּדוֹהִי:
@19 וּלְמִתְּנָךְ עִלָאָה עַל כָּל עַמְמַיָא דִי עֲבַד לְתֻשְׁבָּחָא וּלְשׁוּם וְלִרְבוּ וּלְמֶהֱוָךְ עַם קַדִישׁ קֳדָם יְיָ אֱלָהָךְ כְּמָא דִי מַלִיל:
@20 וּפַקִיד מֹשֶׁה וְסָבֵי יִשְׂרָאֵל יָת עַמָא לְמֵימָר טַר יָת כָּל תַּפְקֶדְתָּא דִי אֲנָא מְפַקֵד יָתְכוֹן יוֹמָא דֵין:
@21 וִיהֵי בְּיוֹמָא דִי תַעְבְּרוּן יָת יַרְדְנָא לְאַרְעָא דַיְיָ אֱלָהָךְ יָהֵב לָךְ וּתְקִים לָךְ אַבְנִין רַבְרְבִין וּתְסוּד יָתְהוֹן בְּסִידָא:
@22 וְתִכְתּוֹב עֲלֵיהוֹן יָת כָּל פִּתְגָמֵי אוֹרַיְתָא הָדָא בְּמֶעְבְּרָךְ בְּדִיל דִי תֵעוּל לְאַרְעָא דַיְיָ אֱלָהָךְ יָהֵב לָךְ אַרְעָא עָבְדָא חֲלַב וּדְבַשׁ כְּמָא דִי מַלִיל יְיָ אֱלָהָא דַאֲבָהָתָךְ לָךְ:
@23 וִיהֵי בְּמֵעֲבָרְכוֹן יָת יַרְדְנָא תְּקִימוּן יָת אַבְנַיָא הָאִלֵין דִי אֲנָא מְפַקֵד יָתְכוֹן יוֹמָא דֵין בְּטּוּרָא דְעֵיבָל וּתְסוּד יָתְהוֹן בְּסִידָא:
@24 וְתִבְנֵי תַמָן מַדְבְּחָא קֳדָם יְיָ אֱלָהָךְ מַדְבַּח אַבְנִין לָא תְרִים עֲלֵיהוֹן פַּרְזְלָא:
@25 אַבְנִין שָׁלְמִין תִּבְנֵי יָת מַדְבְּחָא דַיְיָ אֱלָהָךְ וְתַסֵק עֲלוֹהִי עֲלָוָן קֳדָם יְיָ אֱלָהָךְ:
@26 וְתִכּוֹס נִכְסַת קוּדְשִׁין וְתֵיכוּל תַּמָן וְתֶחֱדֵי קֳדָם יְיָ אֱלָהָךְ:
@27 וְתִכְתּוֹב עַל אַבְנַיָא יָת כָּל פִּתְגָמֵי אוֹרַיְתָא הָדָא פָּרַשׁ יָאוּת:
@28 וּמַלִיל מֹשֶׁה וְכָהֲנַיָא לֵוָאֵי לְכָל יִשְׂרָאֵל לְמֵימָר אֲצֵית וּשְׁמַע יִשְׂרָאֵל יוֹמָא הָדֵין הֲוֵיתָא לְעַמָא קֳדָם יְיָ אֱלָהָךְ:
@29 וּתְקַבֵּל לְמֵימְרָא דַיְיָ אֱלָהָךְ וְתַעְבֵּד יָת פִּקוּדוֹהִי וְיָת קְיָמוֹהִי דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין:
@30 וּפַקִיד מֹשֶׁה יָת עַמָא בְּיוֹמָא הַהוּא לְמֵימָר:
@31 אִלֵין יְקוּמוּן לְבָרָכָא יָת עַמָא עַל טוּרָא דִגְרִזִים בְּמֵעֲבָרְכוֹן יָת יַרְדְנָא שִׁמְעוֹן וְלֵוִי וִיהוּדָה וְיִשָׂשכָר וְיוֹסֵף וּבִנְיָמִין:
@32 וְאִלֵין יְקוּמוּן עַל לְוָטַיָא בְּטוּרָא דְעֵיבָל רְאוּבֵן גָד וְאָשֵׁר וּזְבוּלֻן דָן וְנַפְתָּלִי:
@33 וִיתִיבוּן לֵוָאֵי וְיֵימְרוּן לְכָל אֱנַשׁ יִשְׂרָאֵל קָלָא רָמָא:
@34 לִיט גַבְרָא דִי יַעְבֵּד צֶלֶם וּמַתְּכָא מְרָחָקָא קֳדָם יְיָ עֹבַד יְדֵי אֳמָן וְשַׁוִי בְסִתְרָא וִיתִיבוּן כָּל עַמָא וְיֵימְרוּן אָמֵן:
@35 לִיטּ דְיִקְלֵי אֲבוּהִי וְאִמֵהּ וְיֵימַר כָּל עַמָא אָמֵן:
@36 לִיטּ דְיַשְׁנֵי תְּחוּמָא דְחַבְרֵהּ וְיֵימַר כָּל עַמָא אָמֵן:
@37 לִיט דְיַטְעֵי עַוִירָא בְּאָרְחָא וְיֵימַר כָּל עַמָא אָמֵן:
@38 לִיטּ דְיַצְלֵי דִין דַיַר יִתַּמָא וְאַרְמְלָא וְיֵימַר כָּל עַמָא אָמֵן:
@39 לִיט דְיִשְׁכּוּב עִם אִתַּת אֲבוּהִי אֲרֵי גַלִי כַּנְפָא דַאֲבוּהִי וְיֵימַר כָּל עַמָא אָמֵן:
@40 לִיט דְיִשְׁכּוּב עִם כָּל בְּעִירָא וְיֵימַר כָּל עַמָא אָמֵן:
@41 לִיט דְיִשְׁכּוּב עִם אֲחָתֵהּ בַּת אֲבוּהִי אוֹ בַת אִמֵהּ וְיֵימַר כָּל עַמָא אָמֵן:
@42 לִיט דְיִשְׁכּוּב עִם חֲמוֹתֵהּ וְיֵימַר כָּל עַמָא אָמֵן:
@43 לִיט דְיִמְחֵי לְחַבְרֵהּ בְּסִתְרָא וְיֵימַר כָּל עַמָא אָמֵן:
@44 לִיטּ דִי מְקַבֵּל שׂחֲדָא לְמִקְטַל נְפַשׁ דַם זַכַּי וְיֵימַר כָּל עַמָא אָמֵן:
@45 לִיט דִי לָא יְקַיַם יָת פִּתְגָמֵי אוֹרַיְתָא הָדָא לְמֶעְבַּד יָתְהוֹן וְיֵימַר כָּל עַמָא אָמֵן:
@46 וִיהֵי אִם קַבָּלָא תְקַבֵּל לְמֵימְרָא דַיְיָ אֱלָהָךְ לְמִטַר לְמֶעְבַּד יָת כָּל פִּקוּדוֹהִי דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין וְיִתְּנִנָךְ יְיָ אֱלָהָךְ עִלָאָה עַל כָּל עַמְמֵי אַרְעָא:
@47 וְיֵיתוּן עֲלָךְ כָּל בִּרְכְּתָא הָאִלֵין וְיִדְבְּקֻנָךְ אֲרֵי תְקַבַּל לְמֵימְרָא דַיְיָ אֱלָהָךְ:
@48 בְּרִיךְ אַתְּ בְּקַרְתָּא וּבְרִיךְ אַתְּ בְּחַקְלָא:
@49 בְּרִיךְ וַלְדָא דִמְעָךְ וְאִבָּא דְאַרְעָךְ וּוַלְדָא דִבְעִירָךְ בַּקְרֵי תוֹרָיךְ וְעֶדְרֵי עָנָךְ:
@50 בְּרִיךְ סַלָךְ וְאַצְוָתָךְ:
@51 בְּרִיךְ אַתְּ בְּמֵעֲלָךְ וּבְרִיךְ אַתְּ בְּמִפְּקָךְ:
@52 יִתֵּן יְיָ יָת בַּעֲלֵי דְבָבָךְ דְקָיְמִין עֲלָךְ תְּבִירִין קֳדָמָךְ בְּאָרְחָא חַדָא יִפְּקוּן לְוָתָךְ וּבְשִׁבְעָא אָרְחָן יֵעִרְקוּן מִקֳדָמָךְ:
@53 יְפַקֵד יְיָ עִמָךְ יָת בִּרְכְּתָא בְּאוֹצָרָךְ וּבְכֹל אוֹשָׁטוּת יְדָךְ וִיבָרְכִנָךְ בְּאַרְעָא דַיְיָ אֱלָהָךְ יָהֵב לָךְ:
@54 יְקִימִנָךְ יְיָ לֵהּ לְעַם קַדִישׁ כְּמָא דִי קַיִים לָךְ אֲרֵי תִטַר יָת פִּקוּדַיָא דַיְיָ אֱלָהָךְ וּתְהַךְ בְּאָרְחָן דְתָקְנָן קֳדָמוֹהִי:
@55 וְיֶחֱזוּן כָּל עַמְמֵי אַרְעָא אֲרֵי שְׁמָא דַיְיָ אִתְקְרֵי עֲלָךְ וְיִדְחֲלוּן מִנָךְ:
@56 וְיוֹתְרִנָךְ יְיָ לְטָבָא בְּוַלְדָא דִמְעָךְ וּבְוַלְדָא דִבְעִירָךְ וּבְאִבָּא דְאַרְעָךְ עַל אַרְעָא דִי קַיִים יְיָ לַאֲבָהָתָךְ לְמִתַּן לָךְ:
@57 יִפְתַּח יְיָ לָךְ יָת אוֹצָרֵהּ טָבָא יָת שְׁמַיָא לְמִתַּן מְטַר אַרְעָךְ בְּעִדָנֵהּ וּלְבָרָכָא יָת כָּל עוֹבָדֵי יְדָךְ וְתוֹזֵף לְעַמְמִין סַגִיאִין וְאַתְּ לָא תְזוּף:
@58 וְיִתְּנִנָךְ יְיָ לְתַקִיף וְלָא לְחַלָשׁ וּתְהֵי בְּרַם לְעֵלָא וְלָא תְהֵי לְתַחְתָּא אֲרֵי תְקַבֵּל לְפִקוּדַיָא דַיְיָ אֱלָהָךְ דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין לְמִטַר וּלְמֶעְבָּד:
@59 וְלָא תִסְטוּן מִכָּל פִּתְגָמַיָא דִי אֲנָא מְפַקֵד יָתְכוֹן יוֹמָא דֵין יַמִינָא וּשְׂמָאלָא לִמְהַךְ בָּתַר טַעֲוַת עַמְמַיָא לְמִפְלְחִנוּן:
@60 וִיהֵי אִם לָא תְקַבַּל בְּמֵימְרָא דַיְיָ אֱלָהָךְ לְמִטַר לְמֶעְבַּד יָת כָּל פִּקוּדוֹהִי וּקְיָמוֹהִי דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין וְיֵיתוּן עֲלָךְ כָּל לְוָטַיָא הָאִלֵין וְיִדְבְּקֻנָךְ:
@61 לִיטּ אַתְּ בְּקַרְתָא וְלִיט אַתְּ בְּחַקְלָא:
@62 לִיט סַלָךְ וְאַצְוָתָךְ:
@63 לִיטּ וַלְדָא דִמְעָךְ וְאִבָּא דְאַרְעָךְ בַּקְרֵי תוֹרָיךְ וְעֶדְרֵי עָנָךְ:
@64 לִיט אַתְּ בְּמֵעֲלָךְ וְלִיט אַתְּ בְּמִפְּקָךְ:
@65 יְגָרֵי יְיָ בָּךְ יָת מֵאַרְתָּא וְיָת שִׁגוּשַׁיָא וְיָת מְזוֹפִיתָא בְּכָל אוֹשָׁטוּת יְדָךְ דִי תַעְבֵּד עַד דְתִשְׁתֵּצֵי וְעַד דְתֵיבַד בִּפְרִיעַ מִן קֳדָם בִּישׁוּת עוֹבָדָיךְ דִשְׁבַקְתָּא דַחַלְתִּי:
@66 יַדְבֵּק יְיָ בָּךְ יָת מוֹתָא עַד דִישֵׁיצֵי יָתָךְ מֵעַל אַרְעָא דִי אַתְּ עָלֵל לְתַמָן לְמִירְתַהּ:
@67 יִמְחִנָךְ יְיָ בְּשַׁחֶפְתָּא וּבְקַדַחְתָּא וּבִדְלֶקְתָּא וּבְחַרְחוּרָא וּבְחַרְבָּא וּבְשִׁדְפוֹנָא וּבְיַרְקוֹנָא וְיִרְדְפֻנָךְ עַד דְתֵיבָד:
@68 וִיהוֹן שְׁמַיָךְ דִי עִלָוֵי רֵישָׁךְ חֲסִינִין כִּנְחָשָׁא מִלְאֲחָתָא מִטְרָא וְאַרְעָא דִי תְחוֹתָךְ תַּקִיפָא כְפַרְזְלָא מִלְמֶעְבַּד פֵּרִין:
@69 יִתֵּן יְיָ יָת מְטַר אַרְעָךְ אַבְקָא וְעַפְרָא מִן שְׁמַיָא יֵחוּת עֲלָךְ עַד דְתִשְׁתֵּצֵי:
@70 יִתְּנִנָךְ יְיָ תְּבִיר קֳדָם סָנְאָךְ בְּאָרְחָא חֲדָא תִּפּוֹק לְוָתֵהּ וּבְשִׁבְעָא אָרְחָן תֵּעִרוֹק מִקָדָמוֹהִי וּתְהֵי לְזִיעַ לְכָל מַלְכְּוַת אַרְעָא:
@71 וּתְהֵי נְבִלְתָּךְ מְשַׁגְרָא לְמֵיכַל לְכָל עוֹפָא דִשְׁמַיָא וְלִבְעִירַת אַרְעָא וְלֵית דְמָנִיד:
@72 יִמְחִנָךְ יְיָ בְּשִׁחֲנָא דְמִצְרַיִם וּבִטְּחוֹרִין וּבְגַרְבָּא וּבַחֲרִיס יַבִּישׁ דִי לָא תִכּוּל לְאִתַּסָאָה:
@73 יִמְחִנָךְ יְיָ בְּטַפְשׁוּתָא וּבְסַמְיוּתָא וּבְשַׁעֲמָמוּת לִבָּא:
@74 וּתְהֵי מְמַשֵׁשׁ בְּטִּהֲרָא כְּמָא דִי מַשֵׁשׁ עַוִירָא בְּקַבְלָא וְלָא תַצְלַח יָת אָרְחָתָיךְ וּתְהֵי בְּרַם עָשִׁיק וְאָנִיס כָּל יוֹמַיָא וְלֵית דְפָרִיק:
@75 אִתְּתָא תֵירוֹס וּגְבַר אָחֳרָן יִשְׁכְּבִנַהּ בֵּיתָא תִבְנֵי וְלָא תֵיתֵב בֵּהּ כַּרְמָא תִצוֹב וְלָא תְחַלִנֵהּ:
@76 תּוֹרָךְ יְהֵי נָכֵס לְעֵינָיךְ וְלָא תֵיכוּל מִנֵהּ חֲמָרָךְ יְהֵי אָנֵס מִקֳדָמָךְ וְלָא יְתוּב לָךְ עָנָךְ מְסִירִין לְבַעֲלֵי דְבָבָךְ וְלֵית לָךְ פָּרִיק:
@77 בְּנָיךְ וּבְנָתָיךְ מְסִירִין לְעַמָא אָחָרָן וְעֵינָךְ חֲזָן וִיסוּפָן בִּגְלָלְהֵן כָּל יוֹמָא וְלֵית חֵילָא בִּידָךְ:
@78 אִבָּא דְאַרְעָךְ וְכָל לֵאוּתָךְ יֵכוּל עַמָא דִי לָא יְדַעַתְּ וּתְהֵי בְּרַם עָשִׁיק וּרְעִיעַ כָּל יוֹמַיָא:
@79 וּתְהֵי מִשְׁתַּטֵה מֵחֵזוּ עֵינָיךְ דִי תֶחֱזֵי:
@80 יִמְחִנָךְ יְיָ בְשִׁחֲנָא בִישָׁא עַל רְכֻבַיָא וְעַל שָׁקַיָא דִי לָא תִכּוּל לְאִתַּסָאָה מִפַּרְסַת רַגְלָךְ וְעַד מוֹחָךְ:
@81 יַגְלֵי יְיָ יָתָךְ וְיָת מַלְכָּךְ דִי תְקִים עֲלָךְ לְעַם דִי לָא יְדַעַתְּ אַתְּ וְאַבָהָתָיךְ וְתִפְלַח תַּמָן לְעַמְמַיָא פָּלְחֵי טַעֲוָתָא אָעָא וְאַבְנָא:
@82 וּתְהֵי לְצָדוּ לִמְתַל וּלְשׁוֹעֵי בְכֹל עַמְמַיָא דִי יִדְבְּרִנָךְ יְיָ לְתַמָן:
@83 בַּר זְרַע סַגִי תַּפֵּק לְחַקְלָא וּזְעֵר תִּכְנוֹשׁ אֲרֵי יַחְסְלִנֵהּ גוֹבָא:
@84 כַּרְמִין תִּצוּב וְתִפְלַח וְחַמְרָא לָא תִשְׁתֵּי וְלָא תִכְנוֹשׁ אֲרֵי תֵיכְלִנֵהּ תֹּלַעְתָּא:
@85 זֵיתִין יְהוֹן לָךְ בְּכָל תְּחוּמָךְ וּמִשְׁחָא לָא תְסוּךְ אֲרֵי יִתְּרוּן זֵיתָיךְ:
@86 בְּנִין וּבְנָן תּוֹלִיד וְלָא יְהוֹן לָךְ אֲרֵי יְהָכוּן בְּשִׁבְיָא:
@87 כָּל אִילָנָךְ וְאִבָּא דְאַרְעָךְ יַחְסְנִנֵהּ סַקָאָה:
@88 תּוֹתַב עָרֵל דִי בֵינָךְ יְהֵי סְלִיק עֵיל מִנָךְ לְעֵלָא לְעֵלָא וְאַתְּ תְּהֵי נָחֵת לְתַחְתָּא לְתַחְתָּא:
@89 הוּא יוֹזְפִנָךְ וְאַתְּ לָא תוֹזְפִנֵהּ הוּא יְהֵי לְתַקִיף וְאַתְּ תְּהֵי לְחַלָשׁ:
@90 וְיֵיתוּן עֲלָךְ כָּל לְוָטַּיָא הָאִלֵין וְיִרְדְפֻנָךְ וְיִדְבְּקֻנָךְ עַד דְתִשְׁתֵּצֵי אֲרֵי לָא קַבֶּלְתָּא לְמֵימְרָא דַיְיָ אֱלָהָךְ לְמִטַר פִּקוּדוֹהִי וּקְיָמוֹהִי דִי פַקְדָךְ:
@91 וִיהוֹן בָּךְ לְאָת וּלְמוֹפֵת וּבִבְנָיךְ עַד עֳלָם:
@92 חֳלָף דִי לָא פְלַחְתָּא קֳדָם יְיָ אֱלָהָךְ בְּחֶדְוָא וּבְשַׁפִּירוּת לִבָּא מִסְגֵי כֹּלָא:
@93 וְתִפְלַח יָת בַּעֲלֵי דְבָבָךְ דִי יְגָרִנֵהּ יְיָ בָּךְ בְּכַפְנָא וּבְצַחוּתָא וּבְעַרְטִּלְיָתָא וּבַחֲסִירוּת כֹּלָא וְיִתֵּן נִיר פַּרְזְלָא עַל צַוְארָךְ עַד דִישֵׁיצֵי יָתָךְ:
@94 יַיְתִי יְיָ עֲלָךְ עַם מֵרָחִיק מִסְיָפֵי אַרְעָא כְּמָא דִי מִשְׁתְּדִי נִשְׁרָא עַמָא דִי לָא תִשְׁמַע לִישָׁנֵהּ:
@95 עַם תַּקִיף אַפִּין דִי לָא יִסַב אַפִּין לְסָבָא וְעַל יָנְקָא לָא מְרַחֵם:
@96 וְיֵיכוּל וַלְדָא דִבְעִירָךְ וְאִבָּא דְאַרְעָךְ עַד דְתִשְׁתֵּצֵי דִי לָא יַשְׁאַר לָךְ עִבוּרָא חַמְרָא וּמִשְׁחָא בַּקְרֵי תוֹרָיךְ וְעֶדְרֵי עָנָךְ עַד דְיוֹבֵד יָתָךְ:
@97 וְיָעֵק לָךְ בְּכָל קִרְוָיךְ עַד דְיִכְבַּשׁ שׁוּרָיךְ רָמַיָא וּכְרִיכַיָא דִי אַתְּ רָחֵץ לְאִשְׁתֵּזָבָא בְּהֵן בְּכָל אַרְעָךְ וְיָעֵק לָךְ בְּכָל קִרְוָיךְ בְּכָל אַרְעָךְ דִי יְהַב יְיָ אֱלָהָךְ לָךְ:
@98 וְתֵיכוּל וַלְדָא דִמְעָךְ בְּשַׂר בְּנָיךְ וּבְנָתָיךְ דִי יְהַב לָךְ יְיָ אֱלָהָךְ בִּצְיָרָא וּבְעַקְתָא דְיָעֵק לָךְ סַנְאָךְ:
@99 גַבְרָא דְרַכִּיךְ בָּךְ וְדִמְפַנַק לַחֲדָא תַּבְאֵשׁ עֵינֵהּ בְּאָחוּהִי וּבְאִתַּת קְיָמֵהּ וּבִשְׁאָר בְּנוֹהִי דִי יַשְׁאַר:
@100 מִלְמִתַּן לְחַד מִנְהוֹן מִבְּשַׂר בְּנוֹהִי דִי יֵיכוּל מִדְלָא אִשְׁתָּאַר לֵהּ כֹּלָא בִּצְיָרָא וּבְעַקְתָא דִי יָעֵק לָךְ סָנְאָךְ בְכָל קִרְוָיךְ:
@101 דְרַכִּיכָא בָךְ וְדִמְפַנְקָא דִי לָא נַסִיאַת פַּרְסַת רַגְלַהּ לַאֲחָתָא עַל אַרְעָא מִמְפַנְקוּ וּמֵרַכִּיכוּ תַּבְאֵשׁ עֵינַהּ בִּגְבַר קְיָמַהּ וּבִבְרַהּ וּבִבְרַתַּהּ:
@102 וּבִזְעֵר בְּנָהָא דְיִפְּקוּן מִנַהּ וּבִבְנָהָא דִי תְלִיד אֲרֵי תֵיכְלִנוּן בַּחֲסֵירוּת כֹּלָא בְּסִתְרָא בִּצְיָרָא וּבְעַקְתָא דִי יָעֵק לָךְ סָנְאָךְ בְּקִרְוָיךְ:
@103 אִם לָא תִטַר לְּמֶעְבַּד יָת כָּל פִּתְגָמֵי אוֹרַיְתָא הָדָא דִכְתִיבִין בְּסִפְרָא הָדֵין לְמִדְחַל יָת שְׁמָא יַקִירָא וּדְחִילָא הָדֵין יָת יְיָ אֱלָהָךְ:
@104 וְיַפְרַשׁ יְיָ יָת מְחָתָךְ וְיָת מָחַת בְּנָיךְ מָחָן רַבְרְבָן וּמְהֵימְנָן וּמַכְתְּשִׁין בִּישִׁין וּמְהֵימְנִין:
@105 וְיָתֵב בָּךְ יָת כָּל מַכְתְּשֵׁי מִצְרַיִם דִי דְחֶלְתָּא מִקֳדָמֵיהוֹן וְיִדְבְּקוּן בָּךְ:
@106 אַף כָּל מְרַע וְכָל מָחָא דִי לָא כְתִיבִין בְּסִפְרָא דְאוֹרַיְתָא הָדָא יַיְתִנוּן יְיָ עֲלָךְ עַד דְיִשְׁתֵּצָךְ:
@107 וְתִשְׁתַּאֲרוּן בְּעַם זְעֵר חֳלָף דִי הֲוֵיתוּן כְּכוֹכְבֵי שְׁמַיָא לְמִסְגֵי אֲרֵי לָא קַבֶּלְתָּא לְמֵימְרָא דַיְיָ אֱלָהָךְ:
@108 וִיהֵי כְּמָא דְחַדֵי יְיָ עֲלֵיכוֹן לְאוֹטָבָא יָתְכוֹן וּלְאַסְגָאָה יָתְכוֹן כֵּן יֶחֱדֵי יְיָ עֲלֵיכוֹן לְאוֹבָדָא יָתְכוֹן וּלְשֵׁצָאָה יָתְכוֹן וְתִטַלְטְלוּן מֵעַל אַרְעָא דְאַתְּ עָלֵל לְתַמָן לְמֵירְתַהּ:
@109 וִיבַדְרִנָךְ יְיָ בְּכָל עַמְמַיָא מִסְיָפֵי אַרְעָא וְעַד סְיָפֵי אַרְעָא וְתִפְלַח תַּמָן לְעַמְמַיָא פָּלְחֵי טַעֲוָתָא דִי לָא יְדַעְתְּ אַתְּ וַאֲבָהָתָךְ אָעָא וְאַבְנָא:
@110 וּבְעַמְמַיָא הָאִנוּן לָא תְנוּחַ וְלָא יְהֵי מְנָח לְפַרְסַת רַגְלָךְ וְיִתֵּן יְיָ לָךְ תַּמָן לֵב דָחֵל וְחַשְׁכַת עַיְנִין וּמַפְּחַן נְפָשׁ:
@111 וִיהוֹן חַיָיךְ תְּלָן לָךְ מִקָבֵל וּתְהֵי תָוֵה לֵילְיָא וִימָמָא וְלָא תְהֵימִין בְּחַיָיךְ:
@112 בְּצַפְרָא תֵימַר מָן יִתֵּן רַמְשָׁא וּבְרַמְשָׁא תֵימַר מָן יִתֵּן צַפְרָא מִתַּוְהוּת לִבָּךְ דִי תְהֵי תָוֵה וּמֵחֵזוּ עֵינָיךְ דִי תְהֵי חָזֵי:
@113 וְיָתֵיבִנָךְ יְיָ מִצְרַיִם בִּסְפִינָן בְּאָרְחָא דִי אֲמָרִית לָךְ לָא תוֹסֵף עוֹד לְמֶחְזְיַהּ וְתִזְדַבְּנוּן תַּמָן לְבַעֲלֵי דְבָבָךְ לְעַבְדִין וּלְאַמְהָן וְלֵית דְקָנֵהּ:
@114 אִלֵין פִּתְגָמֵי קְיָמָא דִי פַקִיד יְיָ יָת מֹשֶׁה לְמִגְזַר עִם בְּנֵי יִשְׂרָאֵל בְּאַרְעָא דְמוֹאָב בַּר מִקְיָמָא דִי גְזַר עִמְהוֹן בְּחֹרֵב:
@115 וּקְרָא מֹשֶׁה לְכָל יִשְׂרָאֵל וַאֲמַר לְהוֹן אַתּוּן חֲזֵיתוּן יָת כָּל דִי עֲבַד יְיָ לְעֵינֵיכוֹן בְּאַרְעָא דְמִצְרַיִם לְפַרְעֹה וּלְכָל עַבְדוֹהִי וּלְכָל אַרְעֵהּ:
@116 נִסִין רַבְרְבִין דִי חֲזָאָה עֵינָךְ אָתַיָא וּמוֹפְתַיָא רַבְרְבַיָא הָאִנוּן:
@117 וְלָא יְהַב יְיָ לְכוֹן לִבָּא לְמִדַע וְעַיְנִין לְמֶחֱזֵי וְאֻדְנִין לְמִשְׁמַע עַד יוֹמָא הָדֵין:
@118 וְדַבָּרִית יָתְכוֹן אַרְבְּעִין שְׁנִין בְּמַדְבְּרָא לָא בְלִיאַת כְּסוּתְכוֹן מִנְכוֹן וּמְסָנָךְ לָא:עַדוֹ מֵעַל רַגְלָךְ:
@119 לַחְמָא לָא אֲכַלְתּוּן וַחֲמַר חֲדַת וְעַתִּיק לָא שְׁתֵיתוּן בְּדִיל דְתִדְעוּן אֲרֵי אֲנָא יְיָ אֶלָהֲכוֹן:
@120 וַאֲתֵתוּן לְאַתְרָא הָדֵין וּנְפַק סִיחוֹן מַ לְכָּא דְחֶשְׁבּוֹן וְעוֹג מַ לְכָּא דְמַתְנָן לָקֳדָמוּתָנָא לַאֲגָחָא קְרָבָא וּמְחוֹנוּן:
@121 וּנְסִבְנָא יָת אַרְעֲהוֹן וִיהָבִנַהּ לְאַחֲסָנָא לְשִׁבְטָּא דִרְאוּבֵן וּלְשִׁבְטָא דְגָד וּלְפַלְגוּת שִׁבְטָא דִמְנַשֶׁה:
@122 וְתִטְרוּן יָת פִּתְגָמֵי קְיָמָא הָדָא וְתַעְבְּדוּן יָתְהוֹן בְּדִיל דְתִצְלְחוּן יָת כָּל דִי תַּעְבְּדוּן: פפפ:

@1 **והיה כי תבוא וירשתה וישבת בה.** מגיד שלא נתחיבו בבכורים עד שכבשו את הארץ וחלקוה:
@2 **מראשית.** ולא כל ראשית, שאין כל הפרות חיבין בבכורים אלא שבעת המינין בלבד. נאמר כאן ארץ, ונאמר להלן (לעיל ח, ח) ארץ חטה ושערה וגו' , מה להלן משבעת המינים שנשתבחה בהם ארץ ישראל, אף כאן שבח ארץ ישראל שהן שבעה מינין: **זית שמן.** זית אגורי ששמנו אגור בתוכו: **ודבש.** הוא דבש תמרים: **מראשית.** אדם יורד לתוך שדהו ורואה תאנה שבכרה כורך עליה גמי לסימן ואומר הרי זו בכורים:
@3 **אשר יהיה בימים ההם.** אין לך אלא כהן שבימיך, כמו שהוא: **ואמרת אליו.** שאינך כפוי טובה: **הגדתי היום.** פעם אחת בשנה ולא שתי פעמים:
@4 **ולקח הכהן הטנא מידך.** להניף אותו. כהן מניח ידו תחת יד הבעלים ומניף:
@5 **וענית.** לשון הרמת קול: **ארמי אבד אבי.** מזכיר חסדי המקום. ארמי אבד אבי, לבן, בקש לעקור את הכל, כשרדף אחר יעקב. ובשביל שחשב לעשות, חשב לו המקום כאלו עשה, שאמות העולם חושב להם הקדוש ברוך הוא מחשבה רעה כמעשה: **וירד מצרימה.** ועוד אחרים באו עלינו לכלותנו, שאחרי זאת ירד יעקב למצרים: **במתי מעט.** בשבעים נפש:
@9 **אל המקום הזה.** זה בית המקדש: **ויתן לנו את הארץ.** כמשמעו:
@10 **והנחתו.** מגיד שנוטלו אחר הנחת הכהן ואוחזו בידו כשהוא קורא, וחוזר ומניף:
@11 **ושמחת בכל הטוב.** מכאן אמרו אין קורין מקרא בכורים אלא בזמן שמחה, מעצרת ועד החג, שאדם מלקט תבואתו ופירותיו ויינו ושמנו, אבל מהחג ואלך, מביא ואינו קורא: **אתה והלוי.** אף הלוי חיב בבכורים אם נטעו בתוך עריהם: **והגר אשר בקרבך.** מביא ואינו קורא, שאינו יכול לומר לאבותינו:
@12 **כי תכלה לעשר את כל מעשר תבואתך בשנה השלישית.** כשתגמור להפריש מעשרות של שנה השלישית, קבע זמן הבעור והוידוי בערב הפסח של שנה הרביעית, שנאמר (דברים יד, כח) מקצה שלש שנים תוציא וגו' . נאמר כאן מקץ, ונאמר להלן (שם לא, י) מקץ שבע שנים, לענין הקהל מה להלן רגל אף כאן רגל, אי מה להלן חג הסכות אף כאן חג הסכות, תלמוד לומר כי תכלה לעשר, מעשרות של שנה השלישית רגל שהמעשרות כלין בו, וזהו פסח, שהרבה אילנות יש שנלקטין אחר הסכות, נמצאו מעשרות של שלישית כלין בפסח של רביעית, וכל מי ששיהה מעשרותיו הצריכו הכתוב לבערו מן הבית: **שנת המעשר.** שנה שאין נוהג בה אלא מעשר אחד משני מעשרות שנהגו בשתי שנים שלפניה, ששנה ראשונה של שמטה נוהג בה מעשר ראשון, כמו שנאמר (במדבר יח, כו) כי תקחו מאת בני ישראל את המעשר, ומעשר שני, שנאמר (דברים יד, כג) ואכלת לפני ה' אלהיך מעשר דגנך תירשך ויצהרך, הרי שני מעשרות, ובא ולמדך כאן בשנה השלישית שאין נוהג מאותן שני מעשרות אלא אחד, ואיזה, זה מעשר ראשון. ותחת מעשר שני תן מעשר עני שנאמר כאן **ונתת ללוי.** את אשר לו, הרי מעשר ראשון. **לגר ליתום ולאלמנה.** זה מעשר עני: **ואכלו בשעריך ושבעו.** תן להם כדי שבען מכאן אמרו אין פוחתין לעני בגורן פחות מחצי קב חטים וכו' :
@13 **ואמרת לפני ה' אלהיך.** התודה שנתת מעשרותיך: **בערתי הקדש מן הבית.** זה מעשר שני ונטע רבעי, ולמדך שאם שיהה מעשרותיו של שתי שנים ולא העלם לירושלים, שצריך להעלותם עכשיו: **וגם נתתיו ללוי.** זה מעשר ראשון. וגם, לרבות תרומה ובכורים: **ולגר ליתום ולאלמנה.** זה מעשר עני: **ככל מצותך.** נתתים כסדרן ולא הקדמתי תרומה לבכורים, ולא מעשר לתרומה ולא שני לראשון, שהתרומה קרויה ראשית, שהיא ראשונה משנעשה דגן, וכתיב מלאתך ודמעך לא תאחר (שמות כב, כח) , לא תשנה את הסדר: **לא עברתי ממצותיך.** לא הפרשתי ממין על שאינו מינו ומן החדש על הישן: **ולא שכחתי.** מלברך על הפרשת מעשרות:
@14 **לא אכלתי באני ממנו.** מכאן שאסור לאונן: **ולא בערתי ממנו בטמא.** בין שאני טמא והוא טהור, בין שאני טהור והוא טמא. והיכן הזהר על כך (לעיל יב, יז) לא תוכל לאכל בשעריך. זו אכילת טמאה, כמו שנאמר בפסולי המקדשים (לעיל טו, כב) בשעריך תאכלנו הטמא והטהור וגו' , אבל זה, לא תוכל לאכול דרך אכילת שעריך האמור במקום אחר: **ולא נתתי ממנו למת.** לעשות לו ארון ותכריכין: **שמעתי בקול ה' אלהי.** הביאותיו לבית הבחירה: **עשיתי ככל אשר צויתני.** שמחתי ושמחתי בו:
@15 **השקיפה ממעון קדשך.** עשינו מה שגזרת עלינו, עשה אתה מה שעליך לעשות, שאמרת (ויקרא כו, ג) אם בחקתי תלכו ונתתי גשמיכם בעתם: **אשר נתתה לנו כאשר נשבעת לאבתינו.** לתת לנו וקימת ארץ זבת חלב ודבש:
@16 **היום הזה ה' אלהיך מצוך.** בכל יום יהיו בעיניך חדשים, כאלו בו ביום נצטוית עליהם: **ושמרת ועשית אותם.** בת קול מברכתו הבאת בכורים היום, תשנה לשנה הבאה:
@17 **האמרת.** והאמירך (פסוק יח) אין להם עד מוכיח במקרא. ולי נראה שהוא לשון הפרשה והבדלה. הבדלתי לך מאלהי הנכר להיות לך לאלהים, והוא הפרישך אליו מעמי הארץ להיות לו לעם סגלה. ומצאתי להם עד, והוא לשון תפארת, כמו (תהלים צ''ד) יתאמרו כל פועלי און:
@18 **כאשר דבר לך.** (שמות יט, ה) והייתם לי סגלה:
@19 **ולהיתך עם קדש** וגו' **כאשר דבר.** (ויקרא כ, כו) והייתם לי קדושים:
@20 **שמר את כל המצוה.** לשון הוה גרדנ''ט בלע''ז (בעאבאכטענד) :
@21 **והקמת לך.** בירדן ואחר כך תוציא משם אחרות ותבנה מהן מזבח בהר עיבל. נמצאת אתה אומר, שלשה מיני אבנים היו, שנים עשר בירדן, וכנגדן בגלגל, וכנגדן בהר עיבל, כדאיתא במסכת סוטה (ל''ה) :
@27 **באר היטב.** בשבעים לשון:
@28 **הסכת.** כתרגומו: **היום הזה נהיית לעם.** בכל יום יהיו בעיניך כאלו היום באת עמו בברית:
@31 **לברך את העם.** כדאיתא במסכת סוטה (לב, א) ששה שבטים עלו לראש הר גרזים, וששה לראש הר עיבל, והכהנים והלוים והארון למטה באמצע. הפכו לוים פניהם כלפי הר גרזים ופתחו בברכה, ברוך האיש אשר לא יעשה פסל ומסכה וגו' ואלו ואלו עונין אמן. חזרו והפכו פניהם כלפי הר עיבל ופתחו בקללה ואומרים, (פסוק טו) ארור האיש אשר יעשה פסל וגו' , וכן כלם עד (פסוק כו) ארור אשר לא יקים:
@35 **מקלה אביו.** מזלזל, לשון (לעיל כ''ה) ונקלה אחיך:
@36 **מסיג גבול.** מחזירו לאחוריו וגונב את הקרקע, לשון (ישעיה נט) והסג אחור:
@37 **משגה עור.** הסומא בדבר ומשיאו עצה רעה:
@43 **מכה רעהו בסתר.** על לשון הרע הוא אומר. ראיתי ביסודו של רבי משה הדרשן, אחד עשר ארורים יש כאן, כנגד אחד עשר שבטים. וכנגד שמעון לא כתב ארור, לפי שלא היה בלבו לברכו לפני מותו כשברך שאר השבטים, לכך לא רצה לקללו:
@45 **אשר לא יקים.** כאן כלל את כל התורה כלה וקבלוה עליהם באלה ובשבועה:
@49 **שגר אלפיך.** ולדות בקרך שהבהמה משגרת ממעיה: **ועשתרות צאנך.** כתרגומו. ורבותינו אמרו למה נקרא שמם עשתרות, שמעשירות את בעליהן ומחזיקות אותם כעשתרות הללו שהן סלעים חזקים:
@50 **ברוך טנאך.** פירותיך. דבר אחר טנאך דבר לח שאתה מסנן בסלים: **ומשארתך.** דבר יבש שנשאר בכלי ואינו זב:
@51 **ברוך אתה בבאך וברוך אתה בצאתך.** שתהא יציאתך מן העולם בלא חטא כביאתך לעולם:
@52 **ובשבעה דרכים ינוסו לפניך.** כן דרך הנבהלים לברוח, מתפזרין לכל צד:
@65 **המארה.** חסרון כמו (ויקרא יג, נב) צרעת ממארת: **המהומה.** שגוש קול בהלות:
@67 **בשחפת.** שבשרו נשחף ונפוח: **ובקדחת.** לשון (דברים לב, כב) כי אש קדחה באפי והיא אש של חולים מלויי''ד בלע''ז (פיעבערהימצע) שהיא חמה מאד: **ובדלקת.** חמה יותר מקדחת, ומיני חלאים הם: **ובחרחר.** חולי המחממו תוך הגוף וצמא תמיד למים ובלע''ז אישרדימינ''ט לשון (איוב ל, ל) ועצמי חרה מני חרב (ירמי' ו, כט) נחר מפוח מאש: **ובחרב.** יביא עליך גיסות: **שדפון וירקון.** מכות תבואה שבשדות: **שדפון.** רוח קדים אשלי''דה בלע''ז (זאננפערבראננט) : **ירקון.** יובש ופני התבואה מכסיפין ונהפכין לירקון קמ''א בלע''ז : **עד אבדך.** תרגום עד דתיבד, כלומר עד אבוד אותך שתכלה מאליך:
@68 **והיו שמיך אשר על ראשך נחשת.** קללות הללו משה מפי עצמו אמרן, ושבהר סיני מפי הקדוש ברוך הוא אמרן כמשמען, ושם נאמר (ויקרא כו, יד) ואם לא תשמעו לי, (ויקרא כו, כא) ואם תלכו עמי קרי, וכן הוא אומר (פסוק טו) בקול ה' אלהיך (פסוק כא) ידבק ה' בך, (פסוק כב) יככה ה'. הקל משה בקללותיו לאמרן בלשון יחיד. וגם כן בקללה זו הקל, שבראשונות הוא אומר (ויקרא כו, יט) את שמיכם כברזל ואת ארצכם כנחושה, שלא יהיו השמים מזיעין כדרך שאין הברזל מזיע, ומתוך כך יהא חורב בעולם והארץ תהא מזיעה כדרך שהנחשת מזיע, והיא מרקבת פירותיה, וכאן הוא אומר שמיך נחשת וארצך ברזל, שיהיו שמים מזיעין אף על פי שלא יריקו מטר, מכל מקום לא יהיה חורב של אבדן בעולם, והארץ לא תהא מזיעה כדרך שאין הברזל מזיע, ואין הפרות מרקיבין. ומכל מקום קללה היא, בין שהיא כנחשת בין שהיא כברזל, לא תוציא פרות, וכן השמים לא יריקו מטר:
@69 **מטר ארצך אבק ועפר.** זיקא דבתר מטרא, מטר יורד ולא כל צרכו ואין בו כדי להרביץ את העפר, והרוח באה ומעלה את האבק ומכסה את עשב הזרעים שהן לחים מן המים, ונדבק בהם ונעשה טיט ומתיבש, ומרקיבין:
@70 **לזעוה.** לאימה ולזיע, שיזועו כל שומעי מכותיך ממך, ויאמרו אוי לנו, שלא יבוא עלינו כדרך שבא על אלו:
@72 **בשחין מצרים.** רע היה מאד, לח מבחוץ ויבש מבפנים, כדאיתא בבכורות (מא, א) : **גרב.** שחין לח: **חרס.** שחין יבש כחרס:
@73 **ובתמהון לבב.** אוטם הלב אשטורדישו''ן בלע''ז [תדהמה] :
@74 **עשוק.** בכל מעשיך יהיה ערעור:
@75 **ישגלנה.** לשון שגל, פלגש, והכתוב כנהו לשבח, ישכבנה, ותקון סופרים הוא זה: **תחללנו.** בשנה הרביעית לאכול פריו:
@77 **וכלות אליהם.** מצפות אליהם שישובו ואינם שבים. כל תוחלת שאינה באה, קרויה כליון עינים:
@82 **לשמה.** אשטורדישו''ן [תדהמה] כל הרואה אותך ישום עליך: **למשל.** כשתבא מכה רעה על אדם, יאמרו זו דומה למכת פלוני: **ולשנינה.** לשון (לעיל ו, ז) ושננתם, ידברו בך, וכן תרגומו ולשועי, לשון ספור, ואשתעי:
@83 **יחסלנו.** יכלנו, ועל שם כך נקרא חסיל, שמכלה את הכל:
@85 **כי ישל.** ישיר פירותיו, לשון (לעיל יט, ה) ונשל הברזל:
@87 **יירש הצלצל.** יעשנו הארבה רש מן הפרי: **יירש.** יעני: **צלצל.** מין ארבה. ואי אפשר לפרש יירש לשון ירשה, שאם כן היה לו לכתוב יירש, ולא לשון הורשה וגירושין, שאם כן היה לכתוב יוריש:
@92 **מרב כל.** בעוד שהיה לך כל טוב:
@94 **כאשר ידאה הנשר.** פתאום, ודרך מצלחת, ויקלו סוסיו: **לא תשמע לשונו.** לא תכיר לשונו, וכן (ברא' מא) תשמע חלום לפתר אותו. וכן (שם מב) כי שומע יוסף אינטינדר''י בלע''ז [להבין] :
@97 **עד רדת חמתיך.** לשון רדוי וכבוש:
@98 **ואכלת פרי בטנך בשר בניך** וגו' **במצור.** מחמת שיהיו צרין על העיר ויהיה שם מצוק, עקת רעבון:
@99 **הרך בך והענג.** הוא הרך הוא הענוג, לשון פנוק. ומהתענג ומרך מוכיח עליהם ששניהם אחד, אף על פי שהוא מפנק ודעתו קצה בדבר מאוס, ימתק לו לרעבונו בשר בניו ובנותיו עד כי תרע עינו בבניו הנותרים מתת לאחד מהם מבשר בניו אחיהם אשר יאכל. דבר אחר הרך בך הרחמני ורך הלבב, מרב רעבנותם, יתאכזרו ולא יתנו מבשר בניהם השחוטים לבניהם הנותרים:
@101 **תרע עינה באיש חיקה ובבנה ובבתה.** הגדולים:
@102 **ובשליתה.** בניה הקטנים. בכלן תהא עינה צרה כשתאכל את האחד מלתן לאשר אצלה מן הבשר. נט **והפלא ה' את מכתך.** מפלאות ומבדלות משאר מכות: **ונאמנות.** ליסרך לקים שליחותן:
@105 **אשר יגרת מפניהם.** מפני המכות, כשהיו ישראל רואים מכות משנות הבאות על מצרים, היו יראים מהם שלא יבואו גם עליהם, תדע, שכן כתיב (שמות טו, כו) אם שמע וגו' כל המחלה אשר שמתי במצרים לא אשים עליך, אין מיראין את האדם אלא בדבר שהוא יגור ממנו:
@106 **יעלם.** לשון עליה:
@107 **ונשארתם במתי מעט תחת** וגו' **.** מועטין חלף מרבין:
@108 **כן ישיש ה'.** את אויביכם עליכם להאביד וגו' : **ונסחתם.** לשון עקירה וכן (משלי טו, כה) בית גאים יסח ה':
@109 **ועבדת שם אלהים אחרים.** כתרגומו, לא עבודת אלהות ממש, אלא מעלים מס וגולגליות לכומרי עבודה זרה:
@110 **לא תרגיע.** לא תנוח, כמו (ישעיה כח, יב) וזאת המרגעה: **לב רגז.** לב חרד, כתרגומו דחל, כמו (שם יד, ט) שאול מתחת רגזה לך, (שמות טו, יד) שמעו עמים ירגזון, (שמואל ב' כב, ח) מוסדות השמים ירגזו: **וכליון עינים.** מצפה לישועה ולא תבא:
@111 **חייך תלאים לך.** על הספק, כל ספק קרוי תלוי, שמא אמות היום בחרב הבאה עלינו. ורבותינו דרשו זה הלוקח תבואה מן השוק: **ולא תאמין בחייך.** זה הסומך על הפלטר:
@112 **בבקר תאמר מי יתן ערב.** ויהיה הערב של אמש. **ובערב תאמר מי יתן בקר.** של שחרית, שהצרות מתחזקות תמיד, וכל שעה מרבה קללתה משלפניה:
@113 **באניות.** בספינות, בשביה: **והתמכרתם שם לאיביך.** אתם מבקשים להיות נמכרים להם לעבדים ולשפחות: **ואין קנה.** כי יגזרו עליך הרג וכליון: **והתמכרתם.** בלע''ז איפורוונדרי''ץ וו''ש [ותמכרו עצמכם] . ולא יתכן לפרש והתמכרתם לשון ונמכרתם על ידי מוכרים אחרים, מפני שנאמר אחריו ואין קונה:
@114 **לכרת את בני ישראל.** שיקבלו עליהם את התורה באלה ובשבועה: **מלבד הברית.** קללות שבתורת כהנים שנאמרו בסיני:
@117 **ולא נתן ה' לכם לב לדעת.** להכיר את חסדי הקדוש ברוך הוא ולדבק בו: **עד היום הזה.** שמעתי שאותו היום שנתן משה ספר התורה לבני לוי, כמו שכתוב (לקמן לא, ט) ויתנה אל הכהנים בני לוי, באו כל ישראל לפני משה ואמרו לו, משה רבינו, אף אנו עמדנו בסיני וקבלנו את התורה ונתנה לנו, ומה אתה משליט את בני שבטך עליה, ויאמרו לנו יום מחר לא לכם נתנה, לנו נתנה. ושמח משה על הדבר, ועל זאת אמר להם היום הזה נהיית לעם וגו' (לעיל כז, ט) , היום הזה הבנתי שאתם דבקים וחפצים במקום:
@120 **ותבאו אל המקום הזה.** עתה אתם רואים עצמכם בגדלה וכבוד, אל תבעטו במקום ואל ירום לבבכם, ושמרתם את דברי הברית הזאת. דבר אחר ולא נתן ה' לכם לב לדעת, שאין אדם עומד על סוף דעתו של רבו וחכמת משנתו עד ארבעים שנה, ולפיכך לא הקפיד עליכם המקום עד היום הזה, אבל מכאן ואלך יקפיד ולפיכך (פסוק ח) **ושמרתם את דברי הברית הזאת** וגו' :

@2 **ולקחת מראשית כל פרי האדמה אשר תביא מארצך** . שתקח מראשית כל הפרי אשר תביא אל הבית מארצך אשר ה' אלהיך נותן לך יצוה שיפריש הפרי בשדה ויקרא עליו שם ויביאנו לביתו וישים אותו בכלי ראוי להוליכו לבית הבחירה ולא נתן הכתוב שיעור בהם אלא אפילו גרגיר אחד מכל המין ההוא פוטר כל השדה כדין תרומה שחטה אחת פוטרת את הכרי
@2 "והלכת אל המקום אשר יבחר ה' אלהיך" - כפי פשוטו יזהיר שלא תקריב בכורים באחד משעריך משנבחר הבית כי כמו שהזהיר בשחוטי חוץ בקרבנות כן יזהיר בבכורים אבל חובת הבכורים לאחר שכבשו וחלקו מיד כדברי רש"י (בפסוק א) ובספרי (תבוא ב) והלכת אל המקום אשר יבחר ה' אלהיך לשכן שמו שם זה שילה ובית עולמים ושמא יאמרו כי הבמות אסורות בשני הזמנים האלו אבל גם בנוב וגבעון יקריבו הבכורים אבל בבמת יחיד אינן קריבין דמזבח כתיב ואולי ממה שכתוב (שמות כג יט) ראשית בכורי אדמתך תביא בית ה' אלהיך לא קרבו באהל ובמשכן אלא בשילה שהיה שם בית אבנים ובבית העולמים
@3 **וטעם אל הכהן אשר יהיה בימים ההם** . אל הכהן אשר יהיה שם בימים ההם כי הם נתונים לאנשי משמר ככל הקרבנות לא שיוליך עמו כהן מעירו להקריב בכוריו ורש"י כתב אין לך אלא כהן שיהיה בימיך כמות שהוא ולא הבינותי זה כי בענין הזקן ראוי לומר "אל השופט אשר יהיה בימים ההם" (לעיל יז ט) אע"פ שאינו גדול וחכם כשופטים הראשונים אשר היו לפנינו מן העולם צריך לשמוע לו יפתח בדורו כשמואל בדורו אבל בהקרבת הבכורים למי יביאם אם לא לכהן אשר יהיה בימיו וכן ראיתי בספרי (תבוא ג) ובאת אל הכהן אשר יהיה זו היא שר' יוסי הגלילי אומר וכי תעלה על דעתך כהן שאינו בימיך אלא כהן שהוא מוחזק וכשר לך באותן הימים היה קרוב ונתרחק כשר וכן הוא אומר (קהלת ז י) אל תאמר מה היה שהימים הראשונים היו טובים מאלה וגו' ונראה שהם ידרשו בזה שאם הקריב בכורים או עולה וקרבנות בכהן שהוא בחזקת כשר ולאחר זמן נמצא שהוא בן גרושה הקרבנות כשרין כמו שמוזכר בפרק האחרון של קידושין (סו) ויכנס בו עוד שאם היה קרוב ונתרחק כשר וזה לענין הזקן שאינו נדון על פי קרוב ואינו ענין בבכורים
@3 "הגדתי היום" - בפרי הזה שהבאתי הגדתי והודיתי לשם אלהיך שהביאני לארץ אשר נשבע לאבותינו לתת לנו והנה השם מקיים דבריו ואני מודה ומשבח לשמו וטעם הגדתי כמו ספרתי וכן ויגד משה את דברי העם אל ה' (שמות יט ט) ספור או יהיה פירושו הגדתי לך הכהן ולכל העומדים האלה וההגדה הזו היא לה' אלהיך כלומר לשמו כי באתי אל הארץ אשר נשבע לאבותינו כי הוא הביאני אליו לעבדו בארץ
@14 **לא אכלתי באני ממנו** . אע"פ שהוידוי בכל המעשרות כמדרש וגם נתתיו ללוי ולגר וליתום ולאלמנה (ספרי יג מעשר שני פ"ג ה"י) אבל "לא אכלתי באוני ממנו" יחזור על הקדש לבדו שהוא מעשר שני ונטע רבעי והם שאסורין באונן ובטומאה ולא נתתי ממנו למת לעשות לו ארון ותכריכין לשון רש"י ולא הבינותי זה שהרי מפורש בכתוב (לעיל יד כה כו) שמעשר שני אין מחללין אותו חוץ לירושלים אלא על כסף צורה ובירושלים יתן הכסף על דבר הראוי לאכילה בבקר ובצאן וביין ובשכר ויאכל לפני ה' והרב רבי משה כתב בחבורו (הל' מעשר שני פ"ג ה"י) מעשר שני ניתן לאכילה ושתייה שנאמר ואכלת שם לפני ה' אלהיך וסיכה כשתייה ואסור להוציאו בשאר צרכיו כגון שיקח בו כלים ובגדים ועבדים שנאמר ולא נתתי ממנו למת כלומר לא הוצאתי אותו בדבר שאינו מקיים את הגוף עשה מלת "למת" בכאן כנוי לדברים אשר לא יחיה האדם בהם ואלו דברי הבאי ואחרים מפרשים שמתודה שלא נתן ממנו על ארון ותכריכין אפילו למת שהוא מצוה וכל שכן לחי בטלית וחלוק ובספרי (תבוא יד) ולא נתתי ממנו למת לעשות לו ארון ותכריכין דברי רבי אליעזר אמר לו רבי עקיבא אם למת אסור אף לחי אסור ומה ת"ל לא נתתי ממנו שלא החלפתיו אפילו בדבר טהור פירוש רבי עקיבא דורש ולא נתתי ממנו שלא עשיתי ממנו חליפין אפילו בדבר טהור הראוי לאכילה כענין ששנינו (מעשר שני פ"א מ"א) אין מוכרין אותו ואין מחליפין אותו ולא יאמר אדם לחבירו בירושלים הא לך יין ותן לי שמן ויהיה "למת" על דעתו מחובר למעלה לא אכלתי ממנו באוני למת שאין אנינות אלא למת וראיתי בירושלמי (מעשר שני פ"ב ה"א) רבי אליעזר בשם רבי סימאי אומר לא נתתי ממנו למת מה אנן קיימין אם להביא ארון ותכריכין דבר שאסור לחי לחי אסור כל שכן למת איזה דבר שמותר לחי ואסור למת זו סיכה גם זה לא ידעתי מהו שאם סך בשמן מעשר למת הרי בערו בטומאה וכבר התודה עליו "לא בערתי ממנו בטמא" ובגמרא בפרק הערל (יבמות עד) אמר רבי שמעון בן לקיש משום רבי סימאי מנין למעשר שני שנטמא שמותר לסוכו שנאמר ולא נתתי ממנו למת למת הוא דלא נתתי הא לחי דומיא דמת נתתי איזהו דבר ששוה בחיים ובמתים הוי אומר זו סיכה ושם הקשו ואימא ליקח לו ארון ותכריכין ופירושו שיהיה מותר בחי ליקח לו חלוק כשנטמא כיון דלא קרינא ביה ואכלת שם לפני ה' אלהיך ופירקו "ממנו" מגופו נשאר עכשיו כי הוידוי ב"לא נתתי ממנו למת" מחובר עם "לא בערתי ממנו בטמא" יתודה עליו שלא אכל ממנו טמא ולא נתן מן הטמא למת לסוך אותו אבל במשנה (מעשר שני פ"ה מי"ב) שנינו כדברי רבי אליעזר לא נתתי ממנו למת לא לקחתי ממנו ארון ותכריכין למת לא נתתיו לאוננים אחרים ומשמעות זה שהם דורשים בו שלא נתנו למת לא לגופו של מת בארון ותכריכין ולא לאוננים שלו שהוא מתודה על אנינות שלו ושל אחרים ומפני אנינות של אחרים יתודה על הארון והתכריכין אע"פ שאפילו לחי אסור
@15 **אשר נתת לנו כאשר נשבעת לאבתינו** . לתת לנו וקיימת ארץ זבת חלב ודבש לשון רש"י ואם כן שיעור הכתוב ואת האדמה אשר נתת לנו ארץ זבת חלב ודבש כאשר נשבעת לאבותינו ור"א אמר כי טעמו להיותה כן תמיד כלומר וברך את האדמה אשר נתת לנו להיותה ארץ זבת חלב ודבש ואין צורך בכל זה כי בכלל הדבור או השבועה הנתינה אומר אדם לחברו "נשבעת לי שדה שלך" "אמרת לי מנה" וכן כאשר דבר ה' אלהי אבותיך לך ארץ זבת חלב ודבש (לעיל ו ג) וכבר פירשנו (שם) וכן ויתן לו בית ולחם אמר לו וארץ נתן לו (מלכים א יא יח) ולא יקשה בעיניך בכאן כי לא נזכר בשבועות האבות "ארץ זבת חלב ודבש" כי מאחר שהארץ ההיא בעת ההיא ארץ זבת חלב ודבש הנה נשבע להם בארץ זבת חלב ודבש או "לאבותינו" יוצאי מצרים שנאמר להם (שמות ג ח) אל ארץ זבת חלב ודבש כענין וירעו לנו מצרים ולאבותינו (במדבר כ טו)
@16 **היום הזה ה' אלהיך מצוך לעשות** . הנה השלים משה לבאר את התורה ולחדש כל המצות אשר צוה אותו השם לחדש להם ולכך אמר היום הזה ה' אלהיך מצוך לעשות את החקים האלה ואת המשפטים כי כבר השלמתי לך הכל והזכיר ושמרת ועשית אותם בכל לבבך ובכל נפשך והלב והנפש כבר פירשתים (לעיל ו ה)
@17 **וטעם את ה' האמרת היום** . כיון שקבלתם עליכם כל התורה בפירושיה ובדקדוקיה ובחדושיה הנה גדלתם השם ורוממתם אותו שיהיה הוא לבדו לכם לאלהים לא תודו באל אחר כלל
@17 "וללכת בדרכיו" - שתעשו הטוב והישר ותגמלו חסד איש את רעהו ולשמר חקיו ומצותיו ומשפטיו יזכיר בפרט החוקים והמשפטים כאשר פירשתי (לעיל ד ה) ויכלול במצותיו כל המצות מצות עשה ולא תעשה ולשמע בקלו ככל אשר יצוה לכם משאר המעשים על ידי או על יד שאר הנביאים כאשר פירשתי (לעיל יג ה) ויתכן שיהו "מצותיו" מצות עשה ו"לשמוע בקולו" המניעות כלומר מצות לא תעשה
@18 **ואמר וה' האמירך היום** . כי היום הזה לכם כיום סיני והשם רומם וגדל אתכם בקבול התורה שתהיו לו לעם סגולה מכל העמים ולשמר כל מצותיו כי לכם לבדכם יתן תורתו ויצוה אתכם בכל המצות הרצויות לפניו לא לעם אחר כענין שכתוב (תהלים קמז יט כ) מגיד דבריו ליעקב חקיו ומשפטיו לישראל לא עשה כן לכל גוי
@19 **ולתתך עליון על כל הגוים אשר עשה לתהלה** . שיהללוך כל עמי הארץ בהיות ה' קרוב בכל קראך אליו ולשם שיצא לך שם בגוים בהדרו אשר שם עליך כי אתה נעלה על כלם ולתפארת כי תתפאר עליהם לעשות בהם כל אשר תחפוץ תגזור אומר ויקם לך כענין פן יתפאר עלי ישראל לאמר ידי הושיעה לי (שופטים ז ב) ולהיותך עם קדוש לדבקה בו בסוף ועל דרך האמת לתהלה כי אלהי ישראל הוא תהלתך ושמו הגדול הוא אלהיך ובזה תפארתך כענין שנאמר כי תפארת עוזמו אתה (תהלים פט יח) תפארת ישראל (איכה ב א)
@20 **וטעם ויצו משה וזקני ישראל** . כי אחרי שהשלים משה דבריו צוה לזקנים שידברו גם הם עמו ויזהירו בעם לשמור כל המצות כי כל עם הולך בעצת זקניו וכתיב אשר אנכי מצוה אתכם ולא "אנחנו" כי עיקר הדיבור למשה והזקנים ירימו קולם לאמר לעם שמעו והאזינו ועשו וכן וידבר משה והכהנים הלוים אל כל ישראל וגו' (פסוק ט) כי אמרו הכהנים לעם הסכת ושמע ישראל ומשה אמר היום הזה נהיית לעם אבל ר"א אמר כי שמור את כל המצוה מצות האבנים אשר יזכיר ואיננו נכון
@22 **וכתבת עליהן את כל דברי התורה הזאת** . אמר ר"א בשם הגאון שכתבו עליהם מנין המצות כמו הכתובות בהלכות גדולות כעין אזהרות וטעם "באר היטב" (פסוק ח) הכתיבה ורבותינו אמרו (סוטה לב) בשבעים לשון ומצינו בספר תאגי שהיתה כל התורה כתובה בהן מבראשית עד לעיני כל ישראל בתאגיה וזיוניה ומשם נעתקו התאגין בכל התורה ויתכן שהיו האבנים גדולות מאד או שהיה ממעשה הנסים
@22 "למען אשר תבא אל הארץ" - אמר רבי אברהם כי השם יעזרך אם החלות לשמור מצותיו כי זאת היא המצוה הראשונה לביאתם לארץ ולפי דעתי "למען אשר תבא" רמז לכל דברי התורה יאמר שתכתוב על האבנים כל דברי התורה הזאת בעברך בירדן מיד למען אשר באת אל הארץ כי בעבור התורה באת שמה וכן למען ינוח עבדך ואמתך כמוך וזכרת כי עבד היית (לעיל ה יד טו) ינוח עבדך ואמתך כמוך למען תזכור כי עבד היית או טעמו תכתוב עליהם את כל דברי התורה הזאת להיות לך לזכרון למען אשר תבא אל הארץ ותכבוש אותה ותירש את כל העמים ההם בהיותך זוכר התורה ושומר כל מצותיה
@39 **וטעם כי גלה כנף אביו** . דרך כבוד לאב כי בתורה הזכיר (ויקרא כ יא) ערות אביו גלה וכן הזכיר באשת אחיו ואשת אחי אביו ערותם כי שם יחייב עונש גדול מיתה או כרת והוצרך לנבל הרעה שעשו על כן הזכיר בהם הערוה אבל בכאן להיותו לאלה די להזכיר כי גלה כנף אביו כי בגלוי כנף האב בלבד מחוייב קללה כי מקלה את כבודו וכל מקלה את אביו ארור וכן לא יקח איש את אשת אביו ולא יגלה כנף אביו (לעיל כג א) דרך כבוד שלא יקרב אליה כי אין ראוי לגלות כנפו אשר פרש על אשה דרך חופה כטעם ופרשת כנפך על אמתך (רות ג ט) ולא כמי שמרבה בו אנוסת אביו (יבמות צז)
@45 **אשר לא יקים את דברי התורה הזאת** . כאן כלל את כל התורה כולה וקבלוה עליהם באלה ובשבועה לשון רש"י ולפי דעתי כי הקבלה הזאת שיודה במצות בלבו ויהיו בעיניו אמת ויאמין שהעושה אותן יהיה לו שכר וטובה והעובר עליהן יענש ואם יכפור באחת מהן או תהיה בעיניו בטלה לעולם הנה הוא ארור אבל אם עבר על אחת מהן כגון שאכל החזיר והשקץ לתאותו או שלא עשה סוכה ולולב לעצלה איננו בחרם הזה כי לא אמר הכתוב אשר לא יעשה את דברי התורה הזאת אלא אמר אשר לא יקים את דברי התורה הזאת לעשות כטעם קיימו וקבלו היהודים (אסתר ט כז) והנה הוא חרם המורדים והכופרים ובירושלמי בסוטה (פ"ז ה"ד) ראיתי אשר לא יקים וכי יש תורה נופלת רבי שמעון בן יקים אומר זה החזן רבי שמעון בן חלפתא אומר זה בית דין של מטן דמר רב יהודה ורב הונא בשם שמואל על הדבר הזה קרע יאשיהו ואמר עלי להקים אמר רבי אסי בשם רבי תנחום בר חייא למד ולימד ושמר ועשה והיה ספק בידו להחזיק ולא החזיק הרי זה בכלל ארור ידרשו בהקמה הזאת בית המלך והנשיאות שבידם להקים את התורה ביד המבטלים אותה ואפילו היה הוא צדיק גמור במעשיו והיה יכול להחזיק התורה ביד הרשעים המבטלים אותה הרי זו ארור וזה קרוב לענין שפירשנו ואמרו על דרך אגדה זה החזן שאינו מקים ספרי התורה להעמידן כתקנן שלא יפלו ולי נראה על החזן שאינו מקים ספר תורה על הצבור להראות פני כתיבתו לכל כמו שמפורש במסכת סופרים (יד יד) שמגביהין אותו ומראה פני כתיבתו לעם העומדים לימינו ולשמאלו ומחזירו לפניו ולאחריו שמצוה לכל אנשים והנשים לראות הכתוב ולכרוע ולומר וזאת התורה אשר שם משה וגו' (לעיל ד מד) וכן נוהגין
@54 **יקימך ה' לו לעם קדוש כאשר נשבע לך** . יקרא שבועה הברית אשר כרת עמהם בהר סיני על כל הדברים האלו כי שם נאמר (שמות יט ו) ואתם תהיו לי ממלכת כהנים וגוי קדוש או שהברית אשר כרת עם אברהם (בראשית יז ז) להיות לך לאלהים ולזרעך אחריך יכלול זה וכן אמר (להלן כט יב) למען הקים אותך היום לו לעם והוא יהיה לך לאלהים כאשר דבר לך וכאשר נשבע לאבותיך לאברהם ליצחק וליעקב כי לכולם בא בברית
@58 **וטעם לראש ולא לזנב** . ביאורו לראש לכל העמים ולא לזנב לאחד מכל הגוים כי יתכן שיהיה לראש על עמים רבים וזנב לעם אחד נכבד ממנו והנכון שיתנך לראש מעתה ולא לזנב עד עולם באחד מכל העתים וכן רק למעלה תמיד ולא תהיה למטה לעולם
@59 **ולא תסור מכל הדברים** . נמשך עם "כי תשמע" (פסוק יג) שיבואו עליך כל הברכות האלה כאשר תשמע למצותיו וכאשר לא תסור ימין ושמאל מכל הדברים אשר אנכי מצוך בענין עבודה זרה שאם תלך אחרי אלהים אחרים לעבדם כבר סרת מכל מצותיו ואין חפץ כלל בכל המצות שתעשה ואיננו כדברי בעל ההלכות שמנאו מצות לא תעשה
@63 **פרי בטנך** . ואחר כך טנאך ומשארתך (פסוקים ד ה) כי פרי הבטן הטוב והחביב יותר ובקללה אחר אותו כי העונש יגיעהו תחלה לנכסיו ואם לא ישוב ישיגהו בפרי בטנו וכן הקדים בברכות נגיפת האויבים קודם הברכה באסמיך ובכל משלח ידך (פסוקים ז ח) כי נצוח האויבים הוא להם הכבוד והצורך הגדול בכבוש הארצות ובישיבתם לבטח בין העמים ובקללות הקדים המארה בכל משלח ידך ואחר הנגיפה מפניהם (פסוקים כ כה) כי הוא העונש שיגיע אליהם באחרונה וכן יגלו בסוף
@87 **הצלצל** . על דעת רש"י מין ממיני הארבה וא"כ ראוי היה שיצרף אותו עם פסוק הארבה והתולעת (פסוקים לח לט) ויותר נראה שיהיה צלצל שם למחנה האויב אמר (בפסוק מא) בנים ובנות תוליד ולא יהיו לך לעבוד אותך ולכלכל את שיבתך כי ילכו בשבי לפני האויב ואמר כל עצך ופרי אדמתך אשר לא ישאו לך פירות כאשר הזכיר יירש האויב הבא עליך כי השנה שיבואו עליך יתנו להם חילם והם יאכלום ויקרא החיל "צלצל" בעבור שישמיעו קול מלחמה במחנה וקול שופר ורעם שרים ותרועה מלשון צלצלי שמע וצלצלי תרועה (תהלים קנ ה) ובמנענעים ובצלצלים ( ו ה) וכן ארץ צלצל כנפים (ישעיהו יח א) ארץ המשמעת צלצול כנפיה שהולכות למרחקים כאשר ידאה הנשר ובגמרא (ב"ק קטז) נטלוה מסיקין מאן דתני מסיקין לא משתבש דכתיב יירש הצלצל ומתרגמינן יחסנינה סקאה ומאן דתני מציקים לא משתבש דכתיב במצור ובמצוק כי הוא אצלם שם למביאי האדם במצור ובמצוק ודע כי התוכחות במארה ובמהומה ובמגערת ובדבר והעץ ופרי האדמה ושאר כל התוכחות הם כולם עד כלותו אותך מעל האדמה אשר אתה בא שמה לרשתה אבל אחרי הגלות לא יקלל אותם רק לעבוד שם אלהים אחרים עץ ואבן אבל פעמים שיחזור להוכיחם בארץ כאשר אמר (פסוק לו) יולך השם אותך ואת מלכך אשר תקים עליך אל גוי אשר לא ידעת אתה ואבותיך ועבדת שם אלהים אחרים והוא הגלות שגלינו לרומי על לכת אגריפס המלך שם ואחרי כן ישוב ויאמר (פסוק לח) זרע רב תוציא השדה וגו' ואלה התוכחות בהיותם בארץ כי כן יאמר אחריו (פסוק סג) ונסחתם מעל האדמה שהוא הגלות ועל דעתי גם זה מרמיזותיו אמר יולך ה' אותך ואת מלכך אשר תקים עליך אל גוי אשר לא ידעת על לכת אגריפס המלך לרומי גם יתכן שירמוז למלך אחר קודם לאגריפס והוא אריסתובלוס שתפסו שר צבא רומי ויוליכהו שמה בנחושתים והיו למשל ולשנינה בכל העמים שהיו תמהים על גבורתם אשר מעולם איך נפלו גבורים ויאבדו כלי מלחמתם ואחרי כן בא אגריפס שנית עם שליח מלך רומי בארץ וכבש בארץ יהודה מדינות גדולות מאד ואז נתקיים מה שאמר (פסוק מח) ועבדת את אויביך אשר ישלחנו ה' בך ברעב ובצמא וגו' ואמר ישא ה' עליך גוי מרחוק (פסוק מט) כי באו אספסינוס וטיטוס בנו עם חיל גדול מרומיים בארץ ולכדו כל ערי יהודה הבצורות והצר להם מאד כאשר ידוע בספרים שלכדו גם חומות ירושלים ולא נשאר רק בית המקדש וחומת העזרה והיו אוכלים בשר בניהם ובנותיהם וכאשר נלכדה גם היא אז נתקיים ונסחתם מעל האדמה ואז שבו הרומיים לארצם ובידם גלות ירושלים וביד עמים רבים אשר אתם מיון ומצרים וארם ויתר עמים רבים ונתקיים (פסוק סד) והפיצך ה' בכל העמים וגו' והכתובים הבאים אחר כן עונשם בגלות וכן והיו חייך תלאים לך מנגד (פסוק סו) מפני פחדותינו בגלות ביד העמים הגוזרים עלינו גזירות תמיד והנכון שהוא רמז לדורות ההם שהיו בזמן חרבן הבית השני כי היו מתנכלים להם להאבידם לגמרי על כן אמר אחריו (פסוק סח) והשיבך ה' מצרים באניות שהיה זה כאשר כלו להוציאם מן הארץ ורבותינו אמרו (פתיחתא דאסתר רבה) ולמה למצרים לפי שכעור ורע לעבד כשהוא חוזר לרבו הראשון אם כן הזכיר מצרים דרך תוכחות אבל אחרי היותנו בגלות בארצות אויבינו לא נתקללו מעשה ידינו ולא אלפינו ועשתרות צאננו ולא כרמינו וזיתינו ואשר נזרע בשדה אבל אנחנו בארצות כשאר העמים יושבי הארץ ההיא או בטוב מהם שרחמיו עלינו כי ישיבתנו בגלות היא בהבטחה שאמר לנו (ויקרא כו מד) ואף גם זאת בהיותם בארץ אויביהם לא מאסתים ולא געלתים לכלותם להפר בריתי אתם כי אני ה' אלהיהם וכבר פירשתי בסדר אם בחקותי (שם שם טז) סוד הברית הזאת וכי הוא על זמן גלותנו היום ביד החיה הרביעית ואחר כן יבטיח בגאולה ממנו
@115 **וטעם ויקרא משה אל כל ישראל** . כי אחרי שהשלים לאמר להם דברי הברית קראם עוד שמע ישראל אתם ראיתם וגו' כי לא הלכו מלפניו שהכל מחובר הוא
@119 **לחם לא אכלתם ויין ושכר לא שתיתם** . הטעם לא אכלתם ממנו שתוכלו לחיות ממנו כי עיקר מחיתם במן היתה למען תדעו כי אני ה' אלהיכם המחיה אתכם במעשה הנס ואין טעמו שלא אכלו לחם כלל כמו לחם לא אכלתי ומים לא שתיתי (לעיל ט ט) כי בקצת העתים היה לישראל במדבר לחם כמו שכתוב (שם ב כח כט) אכל בכסף תשבירני ואכלתי ומים בכסף תתן לי ושתיתי כאשר עשו לי בני עשו היושבים בשעיר והמואבים היושבים בער ורבותינו הזכירו (יומא עה) דברים שתגרי אומות העולם מביאים להם במדבר ואפשר עוד כי מעת שירד המן עד בואם אל שעיר לא אכלו לחם כלל כי הלכו במדבר הגדול והנורא אבל בשנת הארבעים קרבו לישוב ונאמר להם (לעיל ב ד ו) ואת העם צו לאמר אתם עוברים בגבול אחיכם בני עשו אכל תשברו מאתם ושם (פסוק ז) כתוב זה ארבעים שנה ה' אלהיך עמך לא חסרת דבר ומן העת ההיא היו האדומים והמואבים מקדימים אותם בלחם ובמים והיו גדולי ישראל קונים מהם ואוכלים לתענוג לא לצורך ולא לשבעה ועיקר המחיה שלהם במן
